'use client'

import { cn } from '@/registry/core/lib/utils'
import { Button } from '@/registry/bases/radix/veil/ui/button'
import { Monitor, Moon, Sun } from 'lucide-react'
import { useTheme } from 'next-themes'
import { useMemo, useState } from 'react'

type ThemeOption = 'system' | 'light' | 'dark'

export const ThemeSwitcher = () => {
    const { theme, setTheme } = useTheme()
    const [hoveredTheme, setHoveredTheme] = useState(null)

    const selectedTheme = (theme ?? 'system') as ThemeOption

    const tooltipLabel = useMemo(() => {
        const activeTheme = hoveredTheme ?? selectedTheme

        switch (activeTheme) {
            case 'light':
                return 'Switch to light theme'
            case 'dark':
                return 'Switch to dark theme'
            case 'system':
            default:
                return 'Switch to system theme'
        }
    }, [hoveredTheme, selectedTheme])

    return (
        <div className="w-fit">
            <div className="-ml-2 mb-2 flex">
                <Button
                    size="icon"
                    variant="ghost"
                    aria-label="switch to system theme"
                    aria-pressed={selectedTheme === 'system'}
                    className={cn(selectedTheme === 'system' && 'text-foreground')}
                    onMouseEnter={() => setHoveredTheme('system')}
                    onMouseLeave={() => setHoveredTheme(null)}
                    onFocus={() => setHoveredTheme('system')}
                    onBlur={() => setHoveredTheme(null)}
                    onClick={() => setTheme('system')}
                >
                    <Monitor />
                </Button>
                <Button
                    size="icon"
                    variant="ghost"
                    aria-label="switch to light theme"
                    aria-pressed={selectedTheme === 'light'}
                    className={cn(selectedTheme === 'light' && 'text-foreground')}
                    onMouseEnter={() => setHoveredTheme('light')}
                    onMouseLeave={() => setHoveredTheme(null)}
                    onFocus={() => setHoveredTheme('light')}
                    onBlur={() => setHoveredTheme(null)}
                    onClick={() => setTheme('light')}
                >
                    <Sun />
                </Button>

                <Button
                    size="icon"
                    variant="ghost"
                    aria-label="switch to dark theme"
                    aria-pressed={selectedTheme === 'dark'}
                    className={cn(selectedTheme === 'dark' && 'text-foreground')}
                    onMouseEnter={() => setHoveredTheme('dark')}
                    onMouseLeave={() => setHoveredTheme(null)}
                    onFocus={() => setHoveredTheme('dark')}
                    onBlur={() => setHoveredTheme(null)}
                    onClick={() => setTheme('dark')}
                >
                    <Moon />
                </Button>
            </div>

            <div
                aria-live="polite"
                className={cn('text-muted-foreground w-fit text-xs leading-none transition-opacity', hoveredTheme ? 'opacity-100' : 'opacity-0')}
            >
                {tooltipLabel}
            </div>
        </div>
    )
}

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

import * as React from 'react'
import { Slot } from '@radix-ui/react-slot'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/registry/core/lib/utils'

const buttonVariants = cva('cursor-pointer active:scale-99 duration-200 font-medium inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-full text-sm font-medium focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0', {
    variants: {
        variant: {
            default: 'bg-foreground text-background hover:brightness-95',
            neutral: 'bg-foreground text-background hover:brightness-95',
            destructive: 'bg-destructive text-destructive-foreground shadow-md hover:bg-destructive/90',
            outline: 'shadow-sm text-foreground shadow-black/6.5 border border-transparent bg-card ring-1 ring-foreground/15 duration-200 hover:bg-muted/50',
            secondary: 'bg-secondary text-secondary-foreground hover:bg-secondary/80',
            ghost: 'hover:bg-foreground/5 text-foreground/75 hover:text-foreground',
            link: 'text-primary underline-offset-4 hover:underline',
        },
        size: {
            default: 'h-8 px-3 py-2',
            sm: 'h-7 px-2.5 text-sm',
            lg: 'h-11 px-6 font-medium text-base',
            icon: 'size-9',
        },
    },
    defaultVariants: {
        variant: 'default',
        size: 'default',
    },
})

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement>, VariantProps<typeof buttonVariants> {
    asChild?: boolean
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : 'button'
    return (
        <Comp
            className={cn(buttonVariants({ variant, size, className }))}
            ref={ref}
            {...props}
        />
    )
})
Button.displayName = 'Button'

export { Button, buttonVariants }
